    <main class="flex flex-1 flex-col gap-5 p-4 md:p-6">
        <header class="flex flex-wrap items-end justify-between gap-3"><div><h1 class="text-2xl font-semibold">Finanzas del negocio</h1><p class="text-sm text-muted-foreground">Flujo de efectivo y resultado económico se muestran por separado.</p></div><div class="flex gap-2"><input :value="month" type="month" class="h-9 rounded-md border bg-transparent px-3 text-sm" @change="changeMonth" /><Button v-if="canManage" as-child><Link href="/finance/records/create">Registrar movimiento</Link></Button></div></header>
        <section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article class="rounded-xl border bg-card p-4"><small>Flujo neto</small><p class="text-xl font-semibold" :class="metrics.cash_flow < 0 ? 'text-destructive' : ''">{{ money(metrics.cash_flow) }}</p><p class="text-xs text-muted-foreground">Entradas {{ money(metrics.cash_in) }} · salidas {{ money(metrics.cash_out) }}</p></article><article class="rounded-xl border bg-card p-4"><small>Resultado {{ month === new Date().toISOString().slice(0,7) ? 'provisional' : '' }}</small><p class="text-xl font-semibold" :class="metrics.profit < 0 ? 'text-destructive' : ''">{{ money(metrics.profit) }}</p><p class="text-xs text-muted-foreground">Ingresos {{ money(metrics.revenue) }} · costos/gastos {{ money(metrics.expenses) }}</p></article><article class="rounded-xl border bg-card p-4"><small>Cuentas por cobrar</small><p class="text-xl font-semibold">{{ money(metrics.receivables) }}</p><Link href="/receivables" class="text-xs text-amber-700">Ver cartera</Link></article><article class="rounded-xl border bg-card p-4"><small>Cuentas por pagar</small><p class="text-xl font-semibold">{{ money(metrics.payables) }}</p></article></section>
