        <section class="grid gap-4 lg:grid-cols-2"><article v-for="group in [{title:'Ingresos administrativos',items:incomeRecords},{title:'Gastos administrativos',items:expenseRecords}]" :key="group.title" class="rounded-xl border bg-card"><h2 class="p-4 font-semibold">{{ group.title }}</h2><div class="divide-y"><div v-for="item in group.items" :key="item.id" class="flex justify-between gap-3 p-4 text-sm"><div><strong>{{ item.document_number }} · {{ item.category }}</strong><p class="text-muted-foreground">{{ item.description }} · {{ item.status }}</p></div><div class="text-right"><strong>{{ money(item.total_amount) }}</strong><p class="text-xs text-muted-foreground">Saldo {{ money(item.balance_amount) }}</p></div></div><p v-if="!group.items.length" class="p-6 text-sm text-muted-foreground">Sin movimientos en el mes.</p></div></article></section>
        <section class="overflow-x-auto rounded-xl border bg-card"><div class="p-4"><h2 class="font-semibold">Trazabilidad contable</h2><form method="get" action="/finance" class="mt-3 flex flex-wrap gap-2"><input type="hidden" name="month" :value="month"/><select name="account_id" :value="filters.account_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Todas las cuentas</option><option v-for="account in accounts" :key="account.id" :value="account.id">{{ account.code }} · {{ account.name }}</option></select><select name="category_id" :value="filters.category_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Todas las categorías</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select><select name="person_id" :value="filters.person_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Todos los terceros</option><option v-for="person in people" :key="person.id" :value="person.id">{{ person.name }}</option></select><Button type="submit" variant="outline">Filtrar</Button></form></div><table class="w-full text-sm"><thead class="border-y bg-muted/40 text-left"><tr><th class="px-4 py-3">Fecha / documento</th><th class="px-4 py-3">Cuenta</th><th class="px-4 py-3">Tercero</th><th class="px-4 py-3">Débito</th><th class="px-4 py-3">Crédito</th></tr></thead><tbody class="divide-y"><tr v-for="line in movements.data" :key="line.id"><td class="px-4 py-3"><strong>{{ line.document }}</strong><small class="block text-muted-foreground">{{ line.date }} · {{ line.entry_description }}</small></td><td class="px-4 py-3">{{ line.account }}</td><td class="px-4 py-3">{{ line.person || '—' }}</td><td class="px-4 py-3">{{ money(line.debit) }}</td><td class="px-4 py-3">{{ money(line.credit) }}</td></tr></tbody></table></section>
